def window_out(m, fill, default):
 o=np.full((m.shape[0]-1,m.shape[1]-1),fill,dtype=int)
 for r in range(o.shape[0]):
  for c in range(o.shape[1]):
   q=m[r:r+2,c:c+2]
   if np.all(q==q[0,0]) and q[0,0]!=default: o[r,c]=q[0,0]
 o=o[np.any(o!=fill,axis=1),:]
 o=o[:,np.any(o!=fill,axis=0)]
 return o
